def _sse_data(payload: dict[str, Any]) -> str:
    return f"data: {json.dumps(payload, ensure_ascii=False)}\n\n"


async def _stream_blocking_progress(
    worker: Callable[[Callable[[dict[str, Any]], None]], dict[str, Any] | None],
    *,
    error_code: str,
) -> AsyncIterator[str]:
    """
    Run a blocking worker in a thread and yield SSE events as progress callbacks fire.

    Previously stream endpoints ran the worker to completion first, then dumped the
    queued events — clients saw a long freeze with no UI updates.
    """
    q: queue.Queue[dict[str, Any] | None] = queue.Queue()
    terminal = {"seen": False}

    def on_progress(ev: dict[str, Any]) -> None:
        if not isinstance(ev, dict):
            return
        if ev.get("type") in ("done", "error"):
            terminal["seen"] = True
        q.put(ev)

    def run() -> None:
        try:
            result = worker(on_progress)
            if not terminal["seen"] and isinstance(result, dict):
                payload = dict(result)
                payload.setdefault("type", "done" if result.get("ok", True) else "error")
                q.put(payload)
        except Exception as err:
            if not terminal["seen"]:
                q.put({"type": "error", "code": error_code, "message": str(err)})
        finally:
            q.put(None)

    threading.Thread(target=run, name=f"sse-{error_code}", daemon=True).start()
    while True:
        item = await asyncio.to_thread(q.get)
        if item is None:
            break
        yield _sse_data(item)


class RecommendBody(BaseModel):
    vramMb: int = 0
    ramMb: int = 0
    hasCuda: bool = False


class DownloadBody(BaseModel):
    profile: str | None = None
    modelIds: list[str] | None = None
    hfEndpoint: str | None = None
    force: bool = False


class EnsureGpuBody(BaseModel):
    force: bool = False


class EnsureAudioSeparateBody(BaseModel):
    force: bool = False


class DetectLanguageBody(BaseModel):
    mediaPath: str
    asrModel: str | None = None
    device: str = "auto"
    durationSec: float = 12.0
    # Skip opening titles/BGM; desktop auto-sense typically starts ~45–180s in.
    startSec: float = 0.0


class MtCueIn(BaseModel):
    id: int | None = None
    text: str = ""
    start: float | None = None
    end: float | None = None


class MtTranslateBody(BaseModel):
    """Text-only machine translation (Opus CT2). No media / ASR required."""
    cues: list[MtCueIn] = Field(default_factory=list)
    language: str = "ja"
    targetLanguage: str = "zh"
    mtModel: str | None = None
    device: str = "auto"


class JobBody(BaseModel):
    task: str = "transcribe"
    mediaPath: str
    outputDir: str | None = None
    language: str = "auto"
    asrModel: str = "sensevoice-small"
    mtModel: str | None = None
    mtBackend: str | None = None
    mtExternal: dict[str, Any] | None = None
    subFormats: list[str] = Field(default_factory=lambda: ["srt"])
    device: str = "auto"
    vad: dict[str, Any] = Field(default_factory=dict)
    audio: dict[str, Any] = Field(default_factory=dict)
    glossary: list[Any] = Field(default_factory=list)
    ffmpegPath: str | None = None
    sync: bool = False
    beamSize: int | None = None
    releaseGpuAfter: bool = False
    dualAss: bool = False
    includeWords: bool = False
    karaokeVtt: bool = False
    perfProfile: str | None = None
    wordTimestamps: bool | None = None
    retranscribe: bool | None = None


def validate_job_mt_fields(req: dict[str, Any]) -> None:
    """Raise HTTPException-friendly ValueError if MT backend config is invalid."""
    from .mt import BACKEND_EXTERNAL, normalize_mt_backend
    from .mt.external_http import MtExternalError, normalize_mt_external

    task = str(req.get("task") or "transcribe").strip()
    if task not in ("translate_mt", "dual"):
        return
    try:
        backend = normalize_mt_backend(req.get("mtBackend") or req.get("mt_backend"))
    except ValueError as err:
        raise ValueError(str(err)) from err
    if backend != BACKEND_EXTERNAL:
        return
    try:
        normalize_mt_external(req.get("mtExternal") or req.get("mt_external"))
    except MtExternalError as err:
        raise ValueError(err.message) from err


class WatchStartBody(BaseModel):
    folder: str
    recursive: bool = True
    intervalSec: float = 15.0
    extensions: list[str] | None = None
    template: dict[str, Any] = Field(default_factory=dict)
    outputDir: str | None = None
    settleSec: float = 2.0
    seedExisting: bool = True


class BatchJobsBody(BaseModel):
    mediaPaths: list[str] = Field(default_factory=list)
    items: list[dict[str, Any]] = Field(default_factory=list)
    template: dict[str, Any] = Field(default_factory=dict)
    batchId: str | None = None
    sync: bool = False


class ScanFolderBody(BaseModel):
    folder: str
    recursive: bool = True
    extensions: list[str] | None = None
    limit: int = 200
    template: dict[str, Any] = Field(default_factory=dict)
    outputDir: str | None = None
    batchId: str | None = None
    sync: bool = False


def build_capabilities() -> dict[str, Any]:
    from .ffmpeg_util import resolve_ffmpeg

    ffmpeg = resolve_ffmpeg()
    gpu = probe_gpu_runtime()
    audio_sep = probe_audio_separate()
    asr_whisper = probe_asr_whisper()
    return {
        "apiVersion": API_VERSION,
        "engineVersion": ENGINE_VERSION,
        "minClientApiMajor": MIN_CLIENT_API_MAJOR,
        "stub": is_stub_mode(),
        "tasks": ["transcribe", "translate_mt", "dual"],
        "asrBackends": ["sensevoice", "whisper"],
        "mtBackends": ["opus-ct2", "external"],
        "vadBackends": ["fsmn", "silero", "whisperseg"],
        "devices": ["auto", "cuda", "cpu"],
        "profiles": list(PROFILES.keys()),
        "subFormats": ["srt", "vtt", "ass", "ass-dual"],
        "asrWhisper": asr_whisper,
        "features": {
            "jobResume": True,
            "jobList": True,
            "glossaryEnforce": True,
            "clipRetranscribe": True,
            "streamingSubtitles": True,
            "dualAss": True,
            "releaseGpuAfter": True,
            "confidenceFilter": True,
            "batchJobs": True,
            "scanFolder": True,
            "includeWords": True,
            "watchFolder": True,
            "batchStatus": True,
            "karaokeVtt": True,
            "mtExternal": True,
            "perfProfile": True,
            "wordTimestamps": True,
            "retranscribe": True,
        },
        "ffmpeg": {"available": bool(ffmpeg), "path": ffmpeg or None},
        "gpuRuntime": {
            "status": gpu.get("status"),
            "hasCuda": gpu.get("hasCuda"),
            "gpuName": gpu.get("gpuName"),
            "vramMb": gpu.get("vramMb"),
            "driverCudaVersion": gpu.get("driverCudaVersion"),
            "cublas12": gpu.get("cublas12"),
            "ctranslate2Cuda": gpu.get("ctranslate2Cuda"),
            "target": gpu.get("target"),
            "hint": gpu.get("hint"),
        },
        "audioSeparate": {
            "status": audio_sep.get("status"),
            "installed": audio_sep.get("installed"),
            "package": audio_sep.get("package"),
            "version": audio_sep.get("version"),
            "hint": audio_sep.get("hint"),
        },
    }


def create_app() -> FastAPI:
    from .logging_setup import configure_engine_logging

    configure_engine_logging(quiet_access=True)
    app = FastAPI(title="Transub Engine", version=ENGINE_VERSION)

    @app.get("/health")
    @app.get("/v1/health")
    def health() -> dict[str, Any]:
        return {
            "ok": True,
            "apiVersion": API_VERSION,
            "engineVersion": ENGINE_VERSION,
            "stub": is_stub_mode(),
        }

    @app.get("/v1/capabilities")
    def capabilities() -> dict[str, Any]:
        return {"ok": True, **build_capabilities()}

    @app.get("/v1/models")
    def models() -> dict[str, Any]:
        return {"ok": True, "models": list_models_status(), "profiles": PROFILES}

    @app.post("/v1/models/recommend")
    def models_recommend(body: RecommendBody) -> dict[str, Any]:
        device = detect_device()
        rec = recommend_profile(
            vram_mb=body.vramMb or int(device.get("vramMb") or 0),
            ram_mb=body.ramMb or int(device.get("ramMb") or 0),
            has_cuda=body.hasCuda or bool(device.get("hasCuda")),
        )
        return {"ok": True, "device": device, **rec}

    @app.post("/v1/models/download")
    async def models_download(body: DownloadBody) -> StreamingResponse:
        def worker(on_progress: Callable[[dict[str, Any]], None]) -> dict[str, Any]:
            return download_models(
                profile=body.profile,
                model_ids=body.modelIds,
                hf_endpoint=body.hfEndpoint,
                force=bool(body.force),
                on_progress=on_progress,
            )

        return StreamingResponse(
            _stream_blocking_progress(worker, error_code="DOWNLOAD_FAILED"),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    @app.post("/v1/models/download-sync")
    def models_download_sync(body: DownloadBody) -> dict[str, Any]:
        try:
            result = download_models(
                profile=body.profile,
                model_ids=body.modelIds,
                hf_endpoint=body.hfEndpoint,
                force=bool(body.force),
            )
            return {"ok": True, **result}
        except Exception as err:
            return JSONResponse(
                status_code=400,
                content={"ok": False, "code": "DOWNLOAD_FAILED", "message": str(err)},
            )

    @app.get("/v1/runtime/gpu")
    def runtime_gpu_status() -> dict[str, Any]:
        return probe_gpu_runtime()

    @app.get("/v1/runtime/asr-whisper")
    def runtime_asr_whisper_status() -> dict[str, Any]:
        """Probe faster-whisper + numpy (needed for Whisper ASR / short-window LID)."""
        return probe_asr_whisper()

    @app.post("/v1/runtime/ensure-gpu")
    def runtime_ensure_gpu(body: EnsureGpuBody = EnsureGpuBody()) -> dict[str, Any]:
        try:
            result = ensure_gpu_runtime(force=bool(body.force))
            status = 200 if result.get("ok") else 400
            if status != 200:
                return JSONResponse(status_code=status, content=result)
            return result
        except Exception as err:
            return JSONResponse(
                status_code=400,
                content={
                    "ok": False,
                    "code": "GPU_RUNTIME_FAILED",
                    "message": str(err),
                },
            )

    @app.post("/v1/runtime/ensure-gpu-stream")
    async def runtime_ensure_gpu_stream(body: EnsureGpuBody = EnsureGpuBody()) -> StreamingResponse:
        def worker(on_progress: Callable[[dict[str, Any]], None]) -> dict[str, Any]:
            return ensure_gpu_runtime(force=bool(body.force), on_progress=on_progress)

        return StreamingResponse(
            _stream_blocking_progress(worker, error_code="GPU_RUNTIME_FAILED"),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    @app.post("/v1/runtime/release-gpu")
    def runtime_release_gpu() -> dict[str, Any]:
        return release_gpu_memory(reason="api")

    @app.get("/v1/runtime/audio-separate")
    def runtime_audio_separate_status() -> dict[str, Any]:
        return probe_audio_separate()

    @app.post("/v1/runtime/ensure-audio-separate")
    def runtime_ensure_audio_separate(
        body: EnsureAudioSeparateBody = EnsureAudioSeparateBody(),
    ) -> dict[str, Any]:
        try:
            result = ensure_audio_separate(force=bool(body.force))
            status = 200 if result.get("ok") else 400
            if status != 200:
                return JSONResponse(status_code=status, content=result)
            return result
        except Exception as err:
            return JSONResponse(
                status_code=400,
                content={
                    "ok": False,
                    "code": "AUDIO_SEPARATE_FAILED",
                    "message": str(err),
                },
            )

    @app.post("/v1/runtime/ensure-audio-separate-stream")
    async def runtime_ensure_audio_separate_stream(
        body: EnsureAudioSeparateBody = EnsureAudioSeparateBody(),
    ) -> StreamingResponse:
        def worker(on_progress: Callable[[dict[str, Any]], None]) -> dict[str, Any]:
            return ensure_audio_separate(force=bool(body.force), on_progress=on_progress)

        return StreamingResponse(
            _stream_blocking_progress(worker, error_code="AUDIO_SEPARATE_FAILED"),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    @app.post("/v1/detect-language")
    def detect_language(body: DetectLanguageBody) -> dict[str, Any]:
        """Short-window spoken-language detection (Whisper encoder; no full ASR job)."""
        try:
            from .asr.whisper_fw import detect_language_short

            result = detect_language_short(
                body.mediaPath,
                asr_model=body.asrModel,
                device=body.device or "auto",
                duration_sec=float(body.durationSec or 12.0),
                start_sec=float(body.startSec or 0.0),
            )
            return result if result.get("ok") else {"ok": False, **result}
        except FileNotFoundError as err:
            return JSONResponse(
                status_code=404,
                content={"ok": False, "code": "MEDIA_NOT_FOUND", "message": str(err)},
            )
        except Exception as err:
            return JSONResponse(
                status_code=400,
                content={"ok": False, "code": "DETECT_LANGUAGE_FAILED", "message": str(err)},
            )

    @app.post("/v1/mt/translate")
    def mt_translate(body: MtTranslateBody) -> dict[str, Any]:
        """Translate subtitle cue texts with Opus (or stub) — no mediaPath required."""
        from .mt import translate_cues

        raw = list(body.cues or [])
        if not raw:
            return JSONResponse(
                status_code=400,
                content={"ok": False, "code": "EMPTY_CUES", "message": "cues is empty"},
            )
        cues: list[dict[str, Any]] = []
        id_list: list[int] = []
        for i, item in enumerate(raw):
            start = float(item.start if item.start is not None else i)
            end = float(item.end if item.end is not None else (start + 1.0))
            if end <= start:
                end = start + 0.5
            cues.append({
                "start": start,
                "end": end,
                "text": str(item.text or ""),
            })
            id_list.append(int(item.id) if item.id is not None else i)
        try:
            translated = translate_cues(
                cues,
                language=str(body.language or "ja"),
                mt_model=body.mtModel,
                device=str(body.device or "auto"),
                target_language=str(body.targetLanguage or "zh"),
            )
            out = []
            for i, cue in enumerate(translated or []):
                out.append({
                    "id": id_list[i] if i < len(id_list) else i,
                    "text": str((cue or {}).get("text") or ""),
                    "start": (cue or {}).get("start"),
                    "end": (cue or {}).get("end"),
                })
            return {"ok": True, "cues": out, "count": len(out)}
        except Exception as err:
            code = getattr(err, "code", None) or "MT_TRANSLATE_FAILED"
            return JSONResponse(
                status_code=400,
                content={"ok": False, "code": str(code), "message": str(err)},
            )

    @app.post("/v1/jobs")
    def create_job(body: JobBody) -> dict[str, Any]:
        req = body.model_dump()
        sync = bool(req.pop("sync", False))
        try:
            validate_job_mt_fields(req)
        except ValueError as err:
            return JSONResponse(
                status_code=400,
                content={"ok": False, "code": "MT_EXTERNAL_CONFIG", "message": str(err)},
            )
        if sync:
            try:
                result = execute_job(req)
                return {"ok": True, "status": "done", "result": result}
            except Exception as err:
                code = getattr(err, "code", None) or "JOB_FAILED"
                return JSONResponse(
                    status_code=400,
                    content={"ok": False, "code": str(code), "message": str(err)},
                )
        job = JOBS.create(req, run_async=True)
        return {"ok": True, "id": job.id, "status": job.status}

    @app.post("/v1/jobs/batch")
    def create_jobs_batch(body: BatchJobsBody) -> dict[str, Any]:
        from .batch import build_batch_requests

        template = dict(body.template or {})
        bid, reqs = build_batch_requests(
            list(body.mediaPaths or []),
            template=template,
            batch_id=body.batchId,
            per_item=list(body.items or []) or None,
        )
        if not reqs:
            return JSONResponse(
                status_code=400,
                content={"ok": False, "code": "BATCH_EMPTY", "message": "no mediaPaths/items"},
            )
        # Validate media exists up-front
        missing = [r["mediaPath"] for r in reqs if not Path(r["mediaPath"]).exists()]
        if missing:
            return JSONResponse(
                status_code=400,
                content={
                    "ok": False,
                    "code": "MEDIA_MISSING",
                    "message": f"{len(missing)} media not found",
                    "missing": missing[:20],
                },
            )
        _, jobs = JOBS.create_batch(reqs, batch_id=bid, run_async=not bool(body.sync))
        return {
            "ok": True,
            "batchId": bid,
            "count": len(jobs),
            "jobs": [
                {"id": j.id, "status": j.status, "mediaPath": j.request.get("mediaPath")}
                for j in jobs
            ],
        }

    @app.post("/v1/jobs/scan-folder")
    def scan_folder_jobs(body: ScanFolderBody) -> dict[str, Any]:
        from .batch import build_batch_requests, scan_media_files

        try:
            files = scan_media_files(
                body.folder,
                recursive=bool(body.recursive),
                extensions=body.extensions,
                limit=int(body.limit or 200),
            )
        except FileNotFoundError as err:
            raise HTTPException(status_code=404, detail=str(err)) from err
        if not files:
            return {"ok": True, "batchId": None, "count": 0, "jobs": [], "scanned": 0}

        template = dict(body.template or {})
        if body.outputDir:
            template["outputDir"] = body.outputDir
        bid, reqs = build_batch_requests(
            [str(p) for p in files],
            template=template,
            batch_id=body.batchId,
        )
        # If shared outputDir set, keep it; else each file uses its parent (already in build)
        _, jobs = JOBS.create_batch(reqs, batch_id=bid, run_async=not bool(body.sync))
        return {
            "ok": True,
            "batchId": bid,
            "count": len(jobs),
            "scanned": len(files),
            "jobs": [{"id": j.id, "status": j.status, "mediaPath": j.request.get("mediaPath")} for j in jobs],
        }

    @app.get("/v1/batches/{batch_id}")
    def get_batch(batch_id: str) -> dict[str, Any]:
        try:
            summary = JOBS.get_batch_summary(batch_id)
        except FileNotFoundError as err:
            raise HTTPException(status_code=404, detail=str(err)) from err
        return {"ok": True, **summary}

    @app.post("/v1/watch/start")
    def watch_start(body: WatchStartBody) -> dict[str, Any]:
        from .watch import WATCHES

        try:
            state = WATCHES.start(
                folder=body.folder,
                recursive=bool(body.recursive),
                interval_s=float(body.intervalSec or 15),
                extensions=body.extensions,
                template=dict(body.template or {}),
                output_dir=body.outputDir,
                settle_s=float(body.settleSec or 2),
                seed_existing=bool(body.seedExisting),
            )
        except FileNotFoundError as err:
            raise HTTPException(status_code=404, detail=str(err)) from err
        return {"ok": True, "watch": WATCHES.get(state.id)}

    @app.get("/v1/watch")
    def watch_list() -> dict[str, Any]:
        from .watch import WATCHES

        return {"ok": True, "watches": WATCHES.list()}

    @app.get("/v1/watch/{watch_id}")
    def watch_get(watch_id: str) -> dict[str, Any]:
        from .watch import WATCHES

        w = WATCHES.get(watch_id)
        if not w:
            raise HTTPException(status_code=404, detail="watch not found")
        return {"ok": True, "watch": w}

    @app.post("/v1/watch/{watch_id}/stop")
    def watch_stop(watch_id: str) -> dict[str, Any]:
        from .watch import WATCHES

        ok = WATCHES.stop(watch_id)
        if not ok:
            raise HTTPException(status_code=404, detail="watch not found")
        return {"ok": True, "stopped": True, "id": watch_id}

    @app.get("/v1/jobs")
    def list_jobs(limit: int = 50) -> dict[str, Any]:
        from .job_store import list_job_snapshots

        # Merge in-memory running jobs with disk snapshots
        from .jobs import JOBS as _jobs

        live: dict[str, dict[str, Any]] = {}
        with _jobs._lock:
            for jid, job in _jobs._jobs.items():
                live[jid] = {
                    "id": job.id,
                    "status": job.status,
                    "createdAt": job.created_at,
                    "updatedAt": job.updated_at,
                    "error": job.error,
                    "request": {
                        k: job.request.get(k)
                        for k in ("task", "mediaPath", "asrModel", "language")
                        if k in job.request
                    },
                    "eventCount": len(job.events),
                    "live": True,
                }
        disk = list_job_snapshots(limit=max(1, min(200, int(limit or 50))))
        for row in disk:
            jid = str(row.get("id") or "")
            if jid and jid not in live:
                live[jid] = {**row, "live": False}
        rows = sorted(
            live.values(),
            key=lambda r: float(r.get("updatedAt") or r.get("createdAt") or 0),
            reverse=True,
        )
        return {"ok": True, "jobs": rows[: max(1, min(200, int(limit or 50)))]}

    @app.get("/v1/jobs/{job_id}")
    def get_job(job_id: str) -> dict[str, Any]:
        job = JOBS.get(job_id)
        if not job:
            raise HTTPException(status_code=404, detail="job not found")
        last_progress = None
        for ev in reversed(job.events):
            if ev.get("type") == "progress" or ev.get("stage"):
                last_progress = ev
                break
        return {
            "ok": True,
            "id": job.id,
            "status": job.status,
            "result": job.result,
            "error": job.error,
            "progress": last_progress,
            "eventCount": len(job.events),
        }

    @app.get("/v1/jobs/{job_id}/events")
    async def job_events(job_id: str) -> StreamingResponse:
        job = JOBS.get(job_id)
        if not job:
            raise HTTPException(status_code=404, detail="job not found")

        async def event_stream() -> AsyncIterator[str]:
            idx = 0
            while True:
                with job._events_lock:
                    batch = list(job.events[idx:])
                    status = job.status
                    event_len = len(job.events)
                for ev in batch:
                    idx += 1
                    yield f"data: {json.dumps(ev, ensure_ascii=False)}\n\n"
                    if ev.get("type") in ("done", "error"):
                        return
                if status in ("done", "error", "cancelled") and idx >= event_len:
                    return
                import asyncio

                await asyncio.sleep(0.2)

        return StreamingResponse(event_stream(), media_type="text/event-stream")

    @app.post("/v1/jobs/{job_id}/cancel")
    def cancel_job(job_id: str) -> dict[str, Any]:
        ok = JOBS.cancel(job_id)
        if not ok:
            raise HTTPException(status_code=404, detail="job not found")
        return {"ok": True, "cancelled": True}

    @app.post("/v1/jobs/{job_id}/resume")
    def resume_job(job_id: str) -> dict[str, Any]:
        """Continue from an asr_done / mt_done checkpoint of a prior job."""
        try:
            job = JOBS.resume(job_id, run_async=True)
        except FileNotFoundError as err:
            raise HTTPException(status_code=404, detail=str(err)) from err
        except Exception as err:
            return JSONResponse(
                status_code=400,
                content={"ok": False, "code": "RESUME_FAILED", "message": str(err)},
            )
        return {
            "ok": True,
            "id": job.id,
            "status": job.status,
            "resumedFrom": job_id,
        }

    @app.get("/v1/jobs/{job_id}/checkpoint")
    def get_job_checkpoint(job_id: str) -> dict[str, Any]:
        from .checkpoint import load_checkpoint

        ckpt = load_checkpoint(job_id)
        if not ckpt:
            raise HTTPException(status_code=404, detail="checkpoint not found")
        return {
            "ok": True,
            "id": job_id,
            "stage": ckpt.get("stage"),
            "sourceCueCount": len(ckpt.get("sourceCues") or []),
            "zhCueCount": len(ckpt.get("zhCues") or []) if ckpt.get("zhCues") is not None else None,
            "savedAt": ckpt.get("savedAt"),
        }

    return app


app = create_app()
